          <button class="retry-button" onclick="location.reload()"><i class="fas fa-redo"></i> 重试</button>
        </div>
      \`;
    }

    try {
      const data = await fetchVersionData();
const legadoData = (data.data && data.data.find(item => item.key == 'legado_aggregate')) || {};
const cloudVersion = String(legadoData.current_version || '');
const updateLog = legadoData.update_log || [];

// 显示版本信息
currentVersion.textContent = \`v\${localVer}\`;
latestVersion.textContent = \`v\${cloudVersion}\`;

// 处理日志（update_log 是数组格式）
if (updateLog.length > 0) {
// 显示最新日志
const latestLog = updateLog[0];
latestLogDate.innerHTML = \`<i class="fas fa-calendar-alt"></i> v\${latestLog.version}\`;
